<script setup>
import {inject,ref,onUnmounted} from 'vue';import VoiceDesign from './VoiceDesign.vue';import I from './Icon.vue';import AssetPicker from './AssetPicker.vue';import MediaPreview from './MediaPreview.vue';import VoiceSampleEditor from './VoiceSampleEditor.vue';import MicrophoneRecorder from './MicrophoneRecorder.vue';import {call} from '../api';
const designing=ref(false);const props=defineProps({page:String});const {state,draft,busy,act,notify,refresh}=inject('studio');const name=ref(''),description=ref(''),assetId=ref(''),picker=ref(false),recordingWorking=ref(false),uploadTab=ref('upload'),profile=ref(''),testText=ref('你好，这是一个声音克隆测试。'),speed=ref(1),resultId=ref(''),sampleEditor=ref(null),sampleReady=ref(false),sampleWorking=ref(false);let mounted=true;
function selectedSample(asset){assetId.value=asset.id;sampleReady.value=false;picker.value=false;if(props.page==='voices'&&!name.value.trim())name.value=asset.name.replace(/\.[^.]+$/,'').slice(0,10);}
onUnmounted(()=>{mounted=false;});
async function recorded(asset,reason){if(!mounted)return;selectedSample(asset);await refresh();if(mounted)notify((reason==='limit'?'已达120秒，':reason==='device-ended'?'麦克风已断开，':'')+'录音已校验导入，可试听、裁剪后保存','success');}
async function voiceOperation(training){
 if(!name.value.trim()||!assetId.value)return notify('请填写名称并选择样本');
 if(!sampleReady.value||sampleWorking.value||recordingWorking.value)return notify('请先结束录音、准备声音样本，并检查裁剪范围');
 if(training&&!state.value.settings.provider.cloneUrl)return notify('声音克隆服务尚未配置，请先保存所选声音样本','error');
 const taskId=draft.value.id,sourceId=assetId.value,sampleName=name.value.trim();sampleWorking.value=true;
 try{const result=await act(training?'训练声音':'保存声音样本',async()=>{const clip=await sampleEditor.value.materialize();if(!mounted||draft.value.id!==taskId||assetId.value!==sourceId)throw Error('当前任务或声音来源已变化，本次裁剪未用于保存或训练');return call(training?'trainVoice':'importVoiceSample',{id:taskId,name:sampleName,sampleId:clip.id});});if(result&&mounted&&draft.value.id===taskId&&assetId.value===sourceId){name.value='';assetId.value='';sampleReady.value=false;if(training)profile.value=result.id;notify(training?'服务返回音色ID，已保存到声音库':'所选声音片段已保存，尚未训练克隆音色','success');}}
 finally{sampleWorking.value=false;}
}
async function saveSample(){if(props.page==='voices')return voiceOperation(false);if(!name.value.trim()||!assetId.value)return notify('请填写名称并选择样本');const r=await act('保存资源',()=>call('saveResource',{type:'avatar',item:{name:name.value,description:description.value,assetId:assetId.value}}));if(r){name.value='';assetId.value='';description.value='';notify('资源已保存到本地库','success');}}
async function train(){return voiceOperation(true);}
async function speech(){const r=await act('测试合成声音',()=>call('testSpeech',{id:draft.value.id,text:testText.value,profile:profile.value,speed:speed.value}));if(r?.stale){notify('语音配置已变化，本次结果仅保留在执行记录，请按新配置重新生成');return;}if(r){resultId.value=r.id;notify('测试音频已生成并通过媒体校验','success');}}
</script>
<template><VoiceDesign v-if="designing" @close="designing=false"/><div class="resource-studio" :class="{voice:page==='voices'}"><article class="studio-form-panel"><header><span class="gradient-icon"><I :name="page==='voices'?'Upload':'Plus'" :size="24"/></span><div><h3>{{page==='voices'?'声音训练':'添加形象'}}</h3><p>{{page==='voices'?'上传音频样本，接入服务后训练专属声音模型':'上传视频文件创建新的形象'}}</p></div><button v-if="page==='voices'" class="voice-design-entry" :disabled="!!busy||sampleWorking||recordingWorking" @click="designing=true">设计新音色</button></header><div class="studio-form-body" :class="{'avatar-form':page==='avatars'}"><div><div v-if="page==='voices'" class="upload-tabs"><button :class="{active:uploadTab==='upload'}" @click="uploadTab='upload'">上传音频</button><button :class="{active:uploadTab==='record'}" @click="uploadTab='record'">直接录音</button></div><button v-if="uploadTab==='upload'||page==='avatars'" class="studio-dropzone" :disabled="!!busy||sampleWorking" @click="picker=true"><I :name="page==='voices'?'Upload':'Video'" :size="38"/><strong>{{state.assets.find(a=>a.id===assetId)?.name||'点击选择'+(page==='voices'?'音频 / 视频':'视频')+'文件'}}</strong><small>{{page==='voices'?'支持MP3、WAV、M4A、MP4等格式，视频会提取音轨。':'支持MP4、MOV、WEBM等视频格式。'}}</small><small>{{page==='voices'?'建议使用清晰、单人、无背景音乐的样本。':'文件会复制到本地素材库，原路径变动不影响已导入素材。'}}</small></button><MicrophoneRecorder v-else :draft-id="draft.id" :disabled="!!busy||sampleWorking" @working="recordingWorking=$event" @recorded="recorded"/><VoiceSampleEditor v-if="page==='voices'&&assetId" ref="sampleEditor" :sample-id="assetId" :draft-id="draft.id" :disabled="!!busy||sampleWorking||recordingWorking" @ready="sampleReady=$event"/></div><div><label>{{page==='voices'?'声音名称':'形象名称'}} <b class="required">*</b><div class="counted-input"><input v-model="name" maxlength="10" :placeholder="page==='voices'?'为这个声音起个名字':'请输入数字人名称'"/><span>{{name.length}} / 10</span></div></label><p v-if="page==='voices'" class="hint">起个名字方便记忆（10个字以内）</p><label v-if="page==='avatars'">描述信息<textarea v-model="description" maxlength="200" placeholder="介绍形象或记录使用场景"></textarea><small class="field-count">{{description.length}} / 200</small></label><button class="primary full" :disabled="!!busy||sampleWorking||recordingWorking||(page==='voices'&&!sampleReady)" @click="page==='voices'?train():saveSample()"><I :name="page==='voices'?'Play':'Upload'" :size="18"/>{{page==='voices'?'开始训练':'保存形象'}}</button><button v-if="page==='voices'" class="text-button full" :disabled="!!busy||sampleWorking||recordingWorking||!sampleReady" @click="saveSample">仅保存声音样本</button><p v-if="page==='voices'" class="hint">训练需要配置实际克隆服务。仅保存样本不会生成克隆音色。</p></div></div></article><article v-if="page==='voices'" class="studio-form-panel"><header><span class="gradient-icon"><I name="Mic" :size="24"/></span><div><h3>声音合成</h3><p>选择声音模型，生成个性化语音</p></div></header><div class="studio-form-body"><label>选择声音模型<select v-model="profile"><option value="">使用设置中的默认音色</option><option v-for="v in state.voices" :key="v.id" :value="v.id">{{v.name}}{{v.remoteId?'':'（仅样本）'}}</option></select></label><label>输入文本<textarea v-model="testText" maxlength="5000"></textarea><small class="field-count">{{testText.length}} / 5000</small></label><label>语速 {{speed}}x<input v-model.number="speed" type="range" min="0.5" max="2" step="0.05"/></label><button class="primary full" :disabled="!!busy" @click="speech"><I name="Volume2"/>生成语音</button><MediaPreview v-if="resultId" :id="resultId" type="audio"/></div></article><AssetPicker v-if="picker" :kind="page==='voices'?'audio':'video'" @close="picker=false" @select="selectedSample"/></div></template>
